package com.troday.api.service;
import com.fasterxml.jackson.databind.JsonNode; import com.troday.api.dto.ApiResponseDto; import com.troday.api.entity.*; import com.troday.api.repository.*; import jakarta.servlet.http.HttpServletRequest; import jakarta.transaction.Transactional; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.web.server.ResponseStatusException; import java.time.*; import java.util.*;
@Service public class ViewingService {
 private final AccountService accounts; private final ViewingProposalRepository proposals; private final ViewingRepository viewings; private final RoomRepository rooms; private final RentalHouseRepository houses; private final ConversationParticipantRepository participants;
 public ViewingService(AccountService a,ViewingProposalRepository p,ViewingRepository v,RoomRepository r,RentalHouseRepository h,ConversationParticipantRepository cp){accounts=a;proposals=p;viewings=v;rooms=r;houses=h;participants=cp;}
 public ApiResponseDto<?> proposalList(HttpServletRequest r){Long me=accounts.authenticatedUserId(r);String status=r.getParameter("status");return ok("GET",proposals.findByTenantIdOrLandlordIdOrderByStartsAtDesc(me,me).stream().filter(p->status==null||status.equals(p.getStatus())).map(this::proposalData).toList());}
 @Transactional public ApiResponseDto<?> createProposal(HttpServletRequest r,JsonNode b){Long tenant=accounts.authenticatedUserId(r);Long roomId=requiredLong(b,"roomId");Room room=rooms.findById(roomId).orElseThrow(()->notFound("Không tìm thấy phòng"));Long conversationId=requiredLong(b,"conversationId");if(!participant(conversationId,tenant))throw forbidden("Bạn không thuộc hội thoại");Long owner=houses.findById(room.getHouseId()).map(RentalHouse::getLandlordId).orElseThrow(()->notFound("Không tìm thấy nhà"));LocalDateTime start=parseTime(text(b,"startsAt"));LocalDateTime end=start.plusMinutes(duration(b));if(!future(start))throw bad("startsAt phải ở tương lai");String key=text(b,"clientRequestKey");if(key.isBlank())throw bad("clientRequestKey là bắt buộc");Optional<ViewingProposal> old=proposals.findByTenantIdAndClientRequestKey(tenant,key);if(old.isPresent())return ok("POST",proposalData(old.get()));if(proposals.findByTenantIdOrLandlordIdOrderByStartsAtDesc(tenant,tenant).stream().anyMatch(p->p.getRoomId().equals(roomId)&&"PENDING".equals(p.getStatus())))throw conflict("Đã có đề nghị chờ cho phòng này");if(overlap(roomId,start,end,null))throw conflict("Thời gian xem phòng bị trùng");ViewingProposal p=new ViewingProposal();p.setRoomId(roomId);p.setHouseId(room.getHouseId());p.setConversationId(conversationId);p.setTenantId(tenant);p.setLandlordId(owner);p.setClientRequestKey(key);p.setStartsAt(start);p.setEndsAt(end);p.setNotes(text(b,"notes"));return ok("POST",proposalData(proposals.save(p)));}
 @Transactional public ApiResponseDto<?> proposalDecision(HttpServletRequest r,Long id,JsonNode b){Long owner=accounts.authenticatedUserId(r);ViewingProposal p=proposals.findById(id).orElseThrow(()->notFound("Không tìm thấy đề nghị"));if(!p.getLandlordId().equals(owner))throw forbidden("Chỉ chủ trọ mới được duyệt");if(!"PENDING".equals(p.getStatus()))throw conflict("Đề nghị không còn chờ");String d=text(b,"decision");if(!Set.of("ACCEPT","REJECT").contains(d))throw bad("decision phải là ACCEPT hoặc REJECT");p.setReviewedById(owner);p.setReviewedAt(LocalDateTime.now());if("REJECT".equals(d)){p.setStatus("REJECTED");p.setRejectionReason(text(b,"reason"));if(p.getRejectionReason().isBlank())throw bad("reason là bắt buộc khi từ chối");Map<String,Object> result=new LinkedHashMap<>();result.put("proposal",proposalData(proposals.save(p)));result.put("viewing",null);return ok("POST",result);}if(overlap(p.getRoomId(),p.getStartsAt(),p.getEndsAt(),null))throw conflict("Thời gian xem phòng bị trùng");Viewing v=toViewing(p);v=viewings.save(v);p.setStatus("ACCEPTED");p.setScheduledViewingId(v.getId());return ok("POST",Map.of("proposal",proposalData(proposals.save(p)),"viewing",viewingData(v)));}
 @Transactional public ApiResponseDto<?> withdrawProposal(HttpServletRequest r,Long id){Long tenant=accounts.authenticatedUserId(r);ViewingProposal p=proposals.findById(id).orElseThrow(()->notFound("Không tìm thấy đề nghị"));if(!p.getTenantId().equals(tenant))throw forbidden("Không có quyền rút đề nghị");if(!"PENDING".equals(p.getStatus()))throw conflict("Đề nghị không còn chờ");p.setStatus("WITHDRAWN");p.setWithdrawnById(tenant);p.setWithdrawnAt(LocalDateTime.now());return ok("POST",proposalData(proposals.save(p)));}
 public ApiResponseDto<?> viewingList(HttpServletRequest r){Long me=accounts.authenticatedUserId(r);String status=r.getParameter("status");return ok("GET",viewings.findByTenantIdOrCreatedByIdOrderByStartsAtDesc(me,me).stream().filter(v->status==null||status.equals(v.getStatus())).map(this::viewingData).toList());}
 public ApiResponseDto<?> viewingDetail(HttpServletRequest r,Long id){return ok("GET",viewingData(memberViewing(r,id)));}
 @Transactional public ApiResponseDto<?> createViewing(HttpServletRequest r,JsonNode b){Long owner=accounts.authenticatedUserId(r);Long roomId=requiredLong(b,"roomId"),tenant=requiredLong(b,"tenantId"),conversation=requiredLong(b,"conversationId");Room room=rooms.findById(roomId).orElseThrow(()->notFound("Không tìm thấy phòng"));RentalHouse house=houses.findById(room.getHouseId()).orElseThrow(()->notFound("Không tìm thấy nhà"));if(!house.getLandlordId().equals(owner)||!participant(conversation,owner)||!participant(conversation,tenant))throw forbidden("Ngữ cảnh hội thoại không hợp lệ");LocalDateTime start=parseTime(text(b,"startsAt"));LocalDateTime end=start.plusMinutes(duration(b));if(!future(start)||overlap(roomId,start,end,null))throw bad("Khung giờ xem không hợp lệ");Viewing v=new Viewing();v.setRoomId(roomId);v.setHouseId(room.getHouseId());v.setConversationId(conversation);v.setTenantId(tenant);v.setCreatedById(owner);v.setStartsAt(start);v.setEndsAt(end);v.setNotes(text(b,"notes"));return ok("POST",viewingData(viewings.save(v)));}
 @Transactional public ApiResponseDto<?> attendance(HttpServletRequest r,Long id,JsonNode b){Long owner=accounts.authenticatedUserId(r);Viewing v=memberViewing(r,id);if(!v.getCreatedById().equals(owner))throw forbidden("Chỉ chủ trọ mới ghi nhận điểm danh");if(!"SCHEDULED".equals(v.getStatus()))throw conflict("Lịch xem không còn đang hẹn");String out=text(b,"outcome");if("ATTENDED".equals(out)){v.setStatus("COMPLETED");v.setAttendanceConfirmedById(owner);v.setAttendanceConfirmedAt(LocalDateTime.now());}else if("NO_SHOW".equals(out))v.setStatus("NO_SHOW");else throw bad("outcome phải là ATTENDED hoặc NO_SHOW");return ok("POST",viewingData(viewings.save(v)));}
 @Transactional public ApiResponseDto<?> cancel(HttpServletRequest r,Long id,JsonNode b){Long me=accounts.authenticatedUserId(r);Viewing v=memberViewing(r,id);if(!v.getTenantId().equals(me)&&!v.getCreatedById().equals(me))throw forbidden("Không có quyền hủy lịch");if(!"SCHEDULED".equals(v.getStatus()))throw conflict("Lịch xem không còn đang hẹn");v.setStatus("CANCELLED");v.setCancelledAt(LocalDateTime.now());v.setCancelledById(me);v.setCancellationReason(text(b,"reason"));return ok("POST",viewingData(viewings.save(v)));}
 @Transactional public ApiResponseDto<?> rentalDecision(HttpServletRequest r,Long id,JsonNode b){Long tenant=accounts.authenticatedUserId(r);Viewing v=memberViewing(r,id);if(!v.getTenantId().equals(tenant))throw forbidden("Chỉ người thuê mới quyết định");if(!"COMPLETED".equals(v.getStatus())||!"WAITING".equals(v.getRentalDecision()))throw conflict("Chưa đủ điều kiện quyết định thuê");String d=text(b,"decision");if(!Set.of("AGREE","DECLINE").contains(d))throw bad("decision phải là AGREE hoặc DECLINE");v.setRentalDecision("AGREE".equals(d)?"AGREED":"DECLINED");v.setRentalDecidedById(tenant);v.setRentalDecidedAt(LocalDateTime.now());return ok("POST",viewingData(viewings.save(v)));}
 private Viewing toViewing(ViewingProposal p){Viewing v=new Viewing();v.setRoomId(p.getRoomId());v.setHouseId(p.getHouseId());v.setConversationId(p.getConversationId());v.setTenantId(p.getTenantId());v.setCreatedById(p.getLandlordId());v.setStartsAt(p.getStartsAt());v.setEndsAt(p.getEndsAt());v.setNotes(p.getNotes());return v;}
 private Viewing memberViewing(HttpServletRequest r,Long id){Long me=accounts.authenticatedUserId(r);Viewing v=viewings.findById(id).orElseThrow(()->notFound("Không tìm thấy lịch xem"));if(!v.getTenantId().equals(me)&&!v.getCreatedById().equals(me))throw forbidden("Không có quyền xem lịch");return v;}
 private boolean participant(Long c,Long u){return participants.findByConversationIdAndUserId(c,u).isPresent();}
 private boolean overlap(Long room,LocalDateTime start,LocalDateTime end,Long ignored){return viewings.findByRoomIdAndStatus(room,"SCHEDULED").stream().anyMatch(v->!Objects.equals(v.getId(),ignored)&&v.getStartsAt().isBefore(end)&&v.getEndsAt().isAfter(start));}
 private int duration(JsonNode b){int n=b!=null&&b.has("durationMinutes")?b.get("durationMinutes").asInt():0;if(!Set.of(30,60,90,120).contains(n))throw bad("durationMinutes phải là 30, 60, 90 hoặc 120");return n;}
 private LocalDateTime parseTime(String raw){try{return OffsetDateTime.parse(raw).toLocalDateTime();}catch(Exception e){try{return LocalDateTime.parse(raw);}catch(Exception x){throw bad("startsAt không hợp lệ");}}}
 private boolean future(LocalDateTime x){return x.isAfter(LocalDateTime.now());}
 private Map<String,Object> proposalData(ViewingProposal p){Map<String,Object> m=new LinkedHashMap<>();m.put("id",p.getId());m.put("roomId",p.getRoomId());m.put("houseId",p.getHouseId());m.put("conversationId",p.getConversationId());m.put("tenantId",p.getTenantId());m.put("landlordId",p.getLandlordId());m.put("startsAt",p.getStartsAt());m.put("endsAt",p.getEndsAt());m.put("status",p.getStatus());m.put("scheduledViewingId",p.getScheduledViewingId());m.put("rejectionReason",p.getRejectionReason());return m;}
 private Map<String,Object> viewingData(Viewing v){Map<String,Object> m=new LinkedHashMap<>();m.put("id",v.getId());m.put("roomId",v.getRoomId());m.put("houseId",v.getHouseId());m.put("conversationId",v.getConversationId());m.put("tenantId",v.getTenantId());m.put("createdById",v.getCreatedById());m.put("startsAt",v.getStartsAt());m.put("endsAt",v.getEndsAt());m.put("status",v.getStatus());m.put("rentalDecision",v.getRentalDecision());m.put("attendanceConfirmedAt",v.getAttendanceConfirmedAt());m.put("cancelledAt",v.getCancelledAt());m.put("cancellationReason",v.getCancellationReason());return m;}
 private Long requiredLong(JsonNode b,String k){if(b==null||!b.hasNonNull(k))throw bad(k+" là bắt buộc");return b.get(k).asLong();}private String text(JsonNode b,String k){return b!=null&&b.hasNonNull(k)?b.get(k).asText():"";}private ApiResponseDto<?> ok(String m,Object d){return ApiResponseDto.ok("/api/v1",m,d);}private ResponseStatusException bad(String m){return new ResponseStatusException(HttpStatus.BAD_REQUEST,m);}private ResponseStatusException conflict(String m){return new ResponseStatusException(HttpStatus.CONFLICT,m);}private ResponseStatusException forbidden(String m){return new ResponseStatusException(HttpStatus.FORBIDDEN,m);}private ResponseStatusException notFound(String m){return new ResponseStatusException(HttpStatus.NOT_FOUND,m);}
}
